WITH metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY event_time, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec, id) AS event_seq_2, NTILE(4) OVER (PARTITION BY session_id ORDER BY duration_sec DESC, id) AS duration_sec_bucket FROM web_events) SELECT s.id, s.session_id, s.event_type, s.event_time, s.duration_sec, s.event_seq, s.event_seq_2, s.duration_sec_bucket, CASE WHEN event_type RLIKE '^(page_view|purchase)$' THEN 'CORE' ELSE 'GROUP_B' END AS event_type_zone, (SELECT SUM(w2.duration_sec) FROM web_events w2 WHERE w2.session_id = s.session_id) AS sum_web_event_duration_sec FROM metrics s ORDER BY event_seq_2 DESC
